#!/usr/bin/env python3
# luxarch:release-docs-read-guides hook v1 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""A release document is written from its writing guides, never from the previous release.

An app keeps two writing guides beside its release documents: `change_logs/writing-guide.md` and
`release_notes/writing-guide.md` (`--doc FLEET-RELEASE-PROCESS`). An agent cutting a release opens
the previous release's files and copies their shape. A previous release that drifted from the guide
then becomes the template, and the drift compounds release after release.

PostToolUse(Read | Bash): a full read of a writing guide is recorded for this session. That means a
Read with no `offset` and no `limit` short of the file's end (the Read tool returns at most 2000
lines), or a `cat` of the guide whose output is neither piped nor redirected. A `cd` earlier in the
command moves where a relative path points.

PreToolUse(Edit | Write | MultiEdit | Bash): a write to any other `.md` file in a `change_logs/` or
`release_notes/` folder is denied until this session has read every writing guide that exists in
the two folders beside it. A shell write is found by its redirect, `tee`, `sed -i` or `perl -i`
target, resolved from the event's directory and from each directory the command `cd`s into. A
writing guide itself, and a folder with no guide, pass.

A guide is recorded by its path inside its own checkout, so reading it in the main checkout counts
for the same guide in a worktree of it, and the other way round.

Not seen: a file written by a program whose target the command does not name (a `python3` heredoc,
a `cp`). The next Edit of that file is judged as usual.

A process gate: it fails OPEN. An event it cannot read, a session with no id, or a record that
cannot be written lets the call through, because a gate that waits for a record it can never see
would block every release document.
"""

from __future__ import annotations

import re
import subprocess
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
from _cmdtext import (
    command_text,
    redirects,
    simple_commands,
    text_field,
    tool_input,
    write_targets,
)
from _ledger import (
    event_cwd,
    guides_read,
    guides_writable,
    read_event,
    record_guide_read,
    session_id,
)

_FOLDERS = ("change_logs", "release_notes")
_GUIDE = "writing-guide.md"
_WRITE_TOOLS = ("Edit", "Write", "MultiEdit", "Bash")
_READ_MAX_LINES = 2000  # what the Read tool returns when no limit is given
_PIPE = re.compile(r"(?<![|>])\|(?!\|)")
# bound to a name: an inline `except (A, B)` formats differently under py314 (PEP 758)
_PATH_ERRORS = (ValueError, OSError)
_KEY_ERRORS = (OSError, ValueError, subprocess.SubprocessError)


def _abs(path: str, base: Path) -> Path:
    p = Path(path).expanduser()
    return p if p.is_absolute() else base / p


def _is_guide(p: Path) -> bool:
    return p.name == _GUIDE and p.parent.name in _FOLDERS


def _key(guide: Path) -> str:
    """A guide's name in the record: its path inside its own checkout."""
    real = guide.resolve()
    try:
        r = subprocess.run(
            ["git", "-C", str(real.parent), "rev-parse", "--show-toplevel"],
            capture_output=True,
            text=True,
            timeout=4,
            check=False,
        )
        top = r.stdout.strip() if r.returncode == 0 else ""
        if top:
            return real.relative_to(Path(top).resolve()).as_posix()
    except _KEY_ERRORS:
        pass
    return real.as_posix()


def _read_in_full(p: Path, ti: dict[str, object]) -> bool:
    offset, limit = ti.get("offset"), ti.get("limit")
    if offset not in (None, 0, 1) or isinstance(offset, bool):
        return False
    try:
        lines = len(p.read_text(encoding="utf-8").splitlines())
    except _PATH_ERRORS:
        return False
    if limit is None:
        return lines <= _READ_MAX_LINES
    return isinstance(limit, int) and not isinstance(limit, bool) and limit >= lines


def _prints_to_screen(raw: str) -> bool:
    """No redirect of the command's standard output (`>`, `>>`, `&>`, `1>`)."""
    return not any(
        r.op.startswith(">") and r.fd in ("", "1", "&")
        for r, _s, _e in redirects(command_text(raw), raw)
    )


def _mark(ev: dict[str, object]) -> int:
    ti = tool_input(ev)
    tool = str(ev.get("tool_name") or "")
    if tool == "Read":
        p = _abs(text_field(ti, "file_path"), event_cwd())
        if _is_guide(p) and _read_in_full(p, ti):
            record_guide_read(_key(p))
    elif tool == "Bash":
        cmd = text_field(ti, "command")
        if _PIPE.search(command_text(cmd)):
            return 0  # piped output is not read in full
        cwd = event_cwd()
        for sc in simple_commands(cmd):
            name = Path(sc.argv[0]).name if sc.argv else ""
            if name == "cd" and len(sc.argv) > 1:
                cwd = _abs(sc.argv[1], cwd)
            elif name == "cat" and _prints_to_screen(sc.raw):
                for arg in sc.argv[1:]:
                    p = _abs(arg, cwd)
                    if _is_guide(p) and p.is_file():
                        record_guide_read(_key(p))
    return 0


def _bases(cmd: str) -> list[Path]:
    """The event's directory, and each directory the command `cd`s into, in order."""
    out = [event_cwd()]
    for sc in simple_commands(cmd):
        if len(sc.argv) > 1 and Path(sc.argv[0]).name == "cd":
            out.append(_abs(sc.argv[1], out[-1]))
    return out


def _targets(ev: dict[str, object]) -> list[Path]:
    ti = tool_input(ev)
    cmd = text_field(ti, "command")
    if not cmd:
        path = text_field(ti, "file_path")
        return [_abs(path, event_cwd())] if path else []
    bases = _bases(cmd)
    return [_abs(t, b) for t in write_targets(cmd) for b in bases]


def _release_doc(p: Path) -> bool:
    return p.suffix == ".md" and p.parent.name in _FOLDERS and p.name != _GUIDE


def _gate(ev: dict[str, object]) -> int:
    if str(ev.get("tool_name") or "") not in _WRITE_TOOLS or not session_id():
        return 0
    docs = [p for p in _targets(ev) if _release_doc(p)]
    if not docs or not guides_writable():
        return 0
    read = set(guides_read())
    missing: list[str] = []
    for doc in docs:
        for folder in _FOLDERS:
            guide = doc.parent.parent / folder / _GUIDE
            if not guide.is_file():
                continue
            key = _key(guide)
            if key not in read and key not in missing:
                missing.append(key)
    if not missing:
        return 0
    print(
        "DENIED: read the release writing guides before writing a release document.\n"
        + "".join(f"  Read {g}  (the Read tool, no offset or limit)\n" for g in missing)
        + "The guides are the template. The previous release's change log and release notes are "
        "not: they may have drifted from the guide, and copying them carries the drift forward.\n"
        "Once both are read, retry this write: it passes. --doc FLEET-RELEASE-PROCESS.",
        file=sys.stderr,
    )
    return 2


def main() -> int:
    ev = read_event()
    if str(ev.get("hook_event_name") or "") == "PostToolUse":
        return _mark(ev)
    return _gate(ev)


if __name__ == "__main__":
    try:
        sys.exit(main())
    except Exception:
        sys.exit(0)
